package gui;import data.DataStore;import model.User;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.*;
public class ExerciseLibraryPanel extends Theme.BackgroundPanel{private final MainApp app;private final JPanel list=new JPanel();private static final String[][] E={{"Zone 2 Walk","30 min","Beginner","Steady cardio • conversational pace"},{"Squats","3 × 12","Beginner","Knees track over toes • controlled"},{"Push-ups","3 × 10","Beginner","Straight body line • full range"},{"Reverse Lunges","3 × 10","Intermediate","Slow descent • stable knee"},{"Plank","3 × 40 sec","Beginner","Brace core • neutral spine"},{"Cardio Intervals","20 min","Intermediate","Alternate hard and easy intervals"},{"Strength Circuit","4 × 8–12","Advanced","Controlled resistance training"},{"Yoga Flow","12 min","All levels","Mobility and recovery"}};public ExerciseLibraryPanel(MainApp a){app=a;setOpaque(false);setLayout(new BorderLayout(12,12));setBorder(new EmptyBorder(22,28,18,28));add(Theme.title("EXERCISE LIBRARY • TECHNIQUE HUB"),BorderLayout.NORTH);list.setOpaque(false);list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));add(Theme.transparentScrollPane(list),BorderLayout.CENTER);JButton back=Theme.secondaryButton("← More");back.addActionListener(e->app.showPanel(MainApp.MORE));add(back,BorderLayout.SOUTH);}public void setVisible(boolean v){super.setVisible(v);if(v)load();}    public void refresh() { load(); }

private void load(){list.removeAll();User u=app.getCurrentUser();for(String[]x:E){JPanel c=Theme.cardPanel(new BorderLayout());c.add(Theme.header(x[0]),BorderLayout.NORTH);c.add(Theme.mutedLabel(x[3]),BorderLayout.CENTER);c.add(Theme.bodyLabel(x[1]+" • "+x[2]),BorderLayout.EAST);if(u!=null){JCheckBox d=new JCheckBox("Done");d.setOpaque(false);d.setForeground(Theme.TEXT);d.setSelected(DataStore.isWorkoutCompleted(u.getUserId(),x[0]));d.addActionListener(e->DataStore.setWorkoutCompleted(u.getUserId(),x[0],d.isSelected()));c.add(d,BorderLayout.WEST);}list.add(c);list.add(Box.createVerticalStrut(8));}list.revalidate();list.repaint();}}
